using Microsoft.AspNetCore.DataProtection;

public class TokenService
{
    private readonly IDataProtector _protector;

    public TokenService(IDataProtectionProvider provider)
    {
        _protector = provider.CreateProtector("TokenService-v1");
    }

    public string Protect(string plainText)
    {
        return _protector.Protect(plainText);
    }

    public string Unprotect(string protectedText)
    {
        return _protector.Unprotect(protectedText);
    }
}

// Usage
var provider = DataProtectionProvider.Create("MyApp");
var service = new TokenService(provider);
var token = service.Protect("secret-data");
var original = service.Unprotect(token); // "secret-data"

public string CreateTimeLimitedToken(string data)
{
    return _protector.Protect(
        data,
        new DataProtectionTokenOptions { Lifetime = TimeSpan.FromHours(24) }
    );
}

// Attempting to unprotect after expiry throws CryptographicException
